I did not add the enrichment fetch. It needs `aap:caps/http-client`, and this node's `with` clause grants only `aap:caps/state-read@0.1.0`. Importing the HTTP interface would exceed the node's authority, so the node reads only the subscriptions store. Its output is unchanged.

```wit
package gen:node;

world node {
    use aap:caps/types@0.1.0.{run-info, subscription-list};

    import aap:caps/state-read@0.1.0;

    export run: func(info: run-info) -> subscription-list;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use aap::caps::state_read;

struct Node;

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        let raw = state_read::get("urls").unwrap_or_default();
        let urls: Vec<String> = raw
            .lines()
            .map(|l| l.trim())
            .filter(|l| !l.is_empty())
            .map(|l| l.to_string())
            .collect();
        SubscriptionList { urls }
    }
}

export!(Node);
```

